# chk: a2 = got, t0 = expected, s4 = id
chk:
    beq  a2, t0, 1f
    mv   s5, ra
    li   t2, 'M'
    sw   t2, 0(s0)
    mv   a1, s4
    jal  ra, puthex
    mv   a1, t0
    jal  ra, puthex
    mv   a1, a2
    jal  ra, puthex
    mv   ra, s5
1:  ret

puthex:
    li   t3, 8
    li   t4, 28
ph1: srl  t5, a1, t4
    andi t5, t5, 0xf
    li   t6, 10
    blt  t5, t6, ph2
    addi t5, t5, 'a' - 10
    j    ph3
ph2: addi t5, t5, '0'
ph3: sw   t5, 0(s0)
